bool isEarHashed(Node* ear) {
    Node* a = ear->prev;
    Node* b = ear;
    Node* c = ear->next;

    if (area(a, b, c) >= 0) return false; // reflex, can't be an ear

    // triangle bbox; min & max are calculated like this for speed
    double minTX = std::min<double>(a->x, std::min<double>(b->x, c->x));
    double minTY = std::min<double>(a->y, std::min<double>(b->y, c->y));
    double maxTX = std::max<double>(a->x, std::max<double>(b->x, c->x));
    double maxTY = std::max<double>(a->y, std::max<double>(b->y, c->y));

    // z-order range for the current triangle bbox;
    int minZ = zOrder(minTX, minTY);
    int maxZ = zOrder(maxTX, maxTY);

    Node* p = ear->nextZ;

    while (p && p->z <= maxZ) {
        if (p != ear->prev && p != ear->next &&
            pointInTriangle(a->x, a->y, b->x, b->y, c->x, c->y, p->x, p->y) &&
            area(p->prev, p, p->next) >= 0) return false;
        p = p->nextZ;
    }

    // look for points in both directions along the curve
    p = ear->prevZ;

    while (p && p->z >= minZ) {
        if (p != ear->prev && p != ear->next &&
            pointInTriangle(a->x, a->y, b->x, b->y, c->x, c->y, p->x, p->y) &&
            area(p->prev, p, p->next) >= 0) return false;
        p = p->prevZ;
    }

    return true;
}
