fn atoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() && (bytes[i] as char).is_whitespace() { i += 1; }
    // C isspace: ' ', '\t', '\n', '\v', '\f', '\r'
    let mut sign = 1i64;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        if bytes[i] == b'-' { sign = -1; }
        i += 1;
    }
    let mut val: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        val = val * 10 + (bytes[i] - b'0') as i64;
        i += 1;
        // clamp to avoid overflow — C atoi is UB on overflow; saturate at i64 then clamp to i32 range
        if val > i32::MAX as i64 + 1 { /* keep accumulating? just saturate */ }
    }
    (sign * val) as i32 // hmm
}
